import{_ as l,a0 as r,w as o,s as d,ao as p,I as n,x as s,a1 as i,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const J=JSON.parse('{"title":"面向 Java 开发人员的 JVM 参数指南 | LCTT x X-CMD","titleTemplate":false,"description":"面向 Java 开发人员的 JVM 参数指南 | LCTT (202205) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"面向 Java 开发人员的 JVM 参数指南 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"面向 Java 开发人员的 JVM 参数指南 | LCTT (202205) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202205/20220414 A guide to JVM parameters for Java developers","title":"面向 Java 开发人员的 JVM 参数指南","tag":"202205","desc":""},"relativePath":"202205/20220414 A guide to JVM parameters for Java developers.md","filePath":"[post].md"}'),h={name:"202205/20220414 A guide to JVM parameters for Java developers.md"};function c(u,a,g,v,b,k){const e=r("Link");return o(),d("div",null,[a[25]||(a[25]=p(`<h1 id="面向-java-开发人员的-jvm-参数指南" tabindex="-1">面向 Java 开发人员的 JVM 参数指南 <a class="header-anchor" href="#面向-java-开发人员的-jvm-参数指南" aria-label="Permalink to “面向 Java 开发人员的 JVM 参数指南”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202205/06/134624iiubdjkqmxaaqhmx.jpg" alt=""></p><blockquote><p>通过理解和使用 JVM 以及 JVM 参数，开发人员和最终用户都可以诊断故障并且提高 Java 应用程序的性能。</p></blockquote><p>当你在编写源代码时，你是在编写人类可以阅读的代码。在将代码编译成机器语言之前，计算机无法执行它。机器语言是一个通用术语，指的是特定机器所需的任意数量的语言。通常，如果你在 Linux 上编译代码，它只能 Linux 上运行；如果你在 Windows 上编译代码，它就只在 Windows 上运行。但是，Java 是不同的，它并不以真实的机器为目标，而是面向 <ruby>Java 虚拟机<rt>Java Virtual Machine</rt></ruby>（JVM）。因此，它可以在任何机器上运行。</p><p>Java 源代码被编译成<ruby>字节码<rt>bytecode</rt></ruby>，然后由安装在计算机上的 JVM 运行。JVM 是一个执行引擎，但我们通常不会直接与它交互。它在后台静默运行，替我们处理 Java 字节码。大多数人不需要考虑，甚至也不需要知道 JVM。但是，了解它的工作原理是对我们来说是非常有用的，因为这会有助于我们调试和优化 Java 代码。例如：</p><ul><li>在生产环境中，你发现已经部署的应用程序可能需要提升性能。</li><li>如果你写的应用程序出错了，开发人员和最终用户都可以选择对问题进行调试。</li><li>如果你想了解关于 JDK（即 <ruby>Java 开发工具包<rt>Java Development Kit</rt></ruby>，用于开发/运行 Java 应用程序）的详细信息，你可以通过查询 JVM 来获取。</li></ul><p>本文介绍了一些基础的 JVM 参数，希望在这些场景中可以提供帮助。</p><p><img src="https://opensource.com/sites/default/files/2022-03/java-jvm-parameters.jpg" alt="JVM 参数"></p><p>（图源：Jayashree Huttanagoudar，CC BY-SA 4.0）</p><h3 id="jvm、jdk-和-jre-有什么不同" tabindex="-1">JVM、JDK 和 JRE 有什么不同？ <a class="header-anchor" href="#jvm、jdk-和-jre-有什么不同" aria-label="Permalink to “JVM、JDK 和 JRE 有什么不同？”">​</a></h3><p>Java 有许多 J 开头的缩略词，包括 JVM、JDK 和 JRE。</p><ul><li><ruby>Java 开发工具包<rt>Java Development Kit</rt></ruby>（JDK）可供需要在代码中使用开发库的程序员使用。</li><li><ruby>Java 运行时环境<rt>Java Runtime Environment</rt></ruby>（JRE）可供想运行 Java 应用程序的人使用。</li><li><ruby>Java 虚拟机<rt>Java Virtual Machine</rt></ruby>（JVM）是运行 Java 字节码的组件。</li></ul><p>JDK 同时包含 JRE 和 JVM，但有些 Java 发行版提供了包含 JRE（包括 JVM）的替代下载。</p><p><img src="https://opensource.com/sites/default/files/2022-03/jdk.jpg" alt="JDK"></p><p>（图源：Jayashree Huttanagoudar，CC BY-SA 4.0）</p><p>Java 是开源的，因此，许多不同的公司都会构建和发行他们自己的 JDK 发行版。你可以在系统上安装多个 JDK，这会对你参与或者运行不同的 Java 项目时很有帮助，因为其中一些项目可能使用旧版本的 JDK。</p><p>你可以使用 <code>alternatives</code> 命令，来查看 Linux 系统上的 JDK 列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ alternatives --config java</span></span>
<span class="line"><span>There are 2 programs that provide java.</span></span>
<span class="line"><span>Selection Command</span></span>
<span class="line"><span>-----------------------------------------------</span></span>
<span class="line"><span>*+ 1 java-11-openjdk.x86_64 (/usr/lib/jvm/java-11-openjdk-11.0.13.0.8-2.fc35.x86_64/bin/java)</span></span>
<span class="line"><span>2 java-1.8.0-openjdk.x86_64 (/usr/lib/jvm/java-1.8.0-openjdk-1.8.0.312.b07-2.fc35.x86_64/jre/bin/java)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Enter to keep the current selection[+], or type selection number:</span></span></code></pre></div><p>如果想要在可用的 JDK 之间进行切换，请再次执行该命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo alternatives --config java</span></span></code></pre></div>`,20)),n("p",null,[a[1]||(a[1]=s("或者可以使用 ",-1)),i(e,{href:"https://opensource.com/%5Bhttps%3A//opensource.com/article/22/3/manage-java-versions-sdkman%5D%28https%3A//opensource.com/article/22/3/manage-java-versions-sdkman%29"},{default:t(()=>[...a[0]||(a[0]=[s("SDKMan",-1)])]),_:1}),a[2]||(a[2]=s("，它可以下载、更新和管理系统中的所有 JDK。",-1))]),a[26]||(a[26]=p(`<h3 id="什么是-jvm-调优" tabindex="-1">什么是 JVM 调优？ <a class="header-anchor" href="#什么是-jvm-调优" aria-label="Permalink to “什么是 JVM 调优？”">​</a></h3><p>JVM 调优指的是，通过调整 JVM 参数，来提高 Java 应用程序性能的过程，它还有助于诊断应用程序的故障。</p><p>通常情况下，在调试之前需要考虑以下几点：</p><ul><li><strong>成本</strong>：有时改进运行代码的硬件可以提高应用程序的性能。这可能看起来像是在“作弊”，但请考虑你愿意花多少时间调整 JVM 参数。有时应用程序需要更多的内存来执行所需的功能，而这点是任何软件技术都无法改变的。</li><li><strong>期望结果</strong>：长期来看，稳定性比性能更重要。如果你的调优对稳定性产生了影响，那么谨慎地选择你的调优参数可能会更好。</li><li><strong>底层问题</strong>：有时，问题可能是主机操作系统的底层问题。那么，在调整 JVM 之前，请确保 JVM 平台按预期工作。</li><li><strong>内存泄漏</strong>：如果你在使用垃圾回收（GC）调优参数，那么，应用程序代码中很可能会存在需要修复的内存泄漏。</li></ul><h3 id="参数类型" tabindex="-1">参数类型 <a class="header-anchor" href="#参数类型" aria-label="Permalink to “参数类型”">​</a></h3><p>JVM 参数可以分为以下三类：标准参数、非标准参数和高级选项。</p><h4 id="标准参数" tabindex="-1">标准参数 <a class="header-anchor" href="#标准参数" aria-label="Permalink to “标准参数”">​</a></h4><p>所有的 JVM 实现都支持标准参数，在终端执行 <code>java</code> 命令来查看标准参数列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ java</span></span>
<span class="line"><span>Usage: java [options] &lt;mainclass&gt; [args...]</span></span>
<span class="line"><span>        (to execute a class)</span></span>
<span class="line"><span>   or  java [options] -jar &lt;jarfile&gt; [args...]</span></span>
<span class="line"><span>        (to execute a jar file)</span></span>
<span class="line"><span></span></span>
<span class="line"><span> where options include:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        -cp &lt;class search path of directories and zip/jar files&gt;</span></span>
<span class="line"><span>        -classpath &lt;class search path of directories and zip/jar files&gt;</span></span>
<span class="line"><span>        --class-path &lt;class search path of directories and zip/jar files&gt;</span></span>
<span class="line"><span>                A : separated list of directories, JAR archives,</span></span>
<span class="line"><span>                and ZIP archives to search for class files.</span></span>
<span class="line"><span>        --enable-preview</span></span>
<span class="line"><span>                allow classes to depend on preview features of this release</span></span>
<span class="line"><span></span></span>
<span class="line"><span>To specify an argument for a long option, you can use --&lt;name&gt;=&lt;value&gt; or</span></span>
<span class="line"><span>--&lt;name&gt; &lt;value&gt;.</span></span></code></pre></div>`,9)),n("p",null,[a[4]||(a[4]=s("这些是所有 JVM 都会包含的标准参数，你可以像使用任何 ",-1)),i(e,{href:"https://opensource.com/%5Bhttps%3A//opensource.com/article/21/8/linux-terminal%5D%28https%3A//opensource.com/article/21/8/linux-terminal%29"},{default:t(()=>[...a[3]||(a[3]=[s("命令行选项",-1)])]),_:1}),a[5]||(a[5]=s(" 一样安全地使用它们。例如，要验证配置的命令选项，创建 VM 并加载主类而不执行主类，请使用：",-1))]),a[27]||(a[27]=p(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ java --dry-run &lt;classfile&gt;</span></span></code></pre></div><h4 id="非标准参数" tabindex="-1">非标准参数 <a class="header-anchor" href="#非标准参数" aria-label="Permalink to “非标准参数”">​</a></h4><p>非标准选项以 <code>-X</code> 开头。这些是通用的，并且特定于 JVM 的特定实现。要列出这些参数，请输入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ java -X</span></span>
<span class="line"><span>-Xbatch disable background compilation</span></span>
<span class="line"><span>-Xbootclasspath/a:&lt;directories and zip/jar files separated by :&gt;</span></span>
<span class="line"><span>append to end of bootstrap class path</span></span>
<span class="line"><span>-Xinternalversion</span></span>
<span class="line"><span>displays more detailed JVM version information than the</span></span>
<span class="line"><span>-version option</span></span>
<span class="line"><span>-Xloggc:&lt;file&gt; log GC status to a file with time stamps</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>在这些参数可能会不经通知就发生变化。而且，并非所有 JVM 实现都支持这些参数。</p><p>微软构建的 JVM 可能与 RedHat 构建的 JVM 有不同的参数，诸如此类。</p><p>要获取详细的 JVM 版本信息，请使用如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ java -Xinternalversion --version</span></span>
<span class="line"><span>OpenJDK 64-Bit Server VM (11.0.13+8) for linux-amd64 JRE (11.0.13+8), built on Nov 8 2021 00:00:00 by &quot;mockbuild&quot; with gcc 11.2.1 20210728 (Red Hat 11.2.1-1)</span></span></code></pre></div><p>要获取这些属性设置，请使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ java -XshowSettings:properties --version</span></span></code></pre></div><h4 id="高级选项" tabindex="-1">高级选项 <a class="header-anchor" href="#高级选项" aria-label="Permalink to “高级选项”">​</a></h4><p>这些参数不是随意使用的，而是用于调整 Hotspot VM 的特定区域。这些参数可能会发生变化，并且不能保证得到所有 JVM 实现的支持。</p><p>这些参数以 <code>-XX</code> 开头。如需列出参数列表，使用如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ java -XX:+UnlockDiagnosticVMOptions -XX:+PrintFlagsFinal -version</span></span></code></pre></div><p>例如，需要跟踪类的加载，那么使用下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ java -XX:+TraceClassLoading Hello</span></span></code></pre></div><p>在 <code>Hello.java</code> 中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>public class Hello {</span></span>
<span class="line"><span>  public static void main(String[] args) {</span></span>
<span class="line"><span>    System.out.println(&quot;Inside Hello World!&quot;);</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>另一个可能会面临的问题是 OOM（<ruby>内存超出<rt>Out Of Memory</rt></ruby>）错误，它发生的时候可能没有太多的调试信息。为了解决这个问题，使用调试参数 <code>-XX:+HeapDumpOnOutOfMemoryError</code>，它可以创建一个带有调试信息的 <code>.hprof</code> 文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>// TestClass.java</span></span>
<span class="line"><span>import java.util.ArrayList;</span></span>
<span class="line"><span>import java.util.List;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>public class TestClass {</span></span>
<span class="line"><span>  public static void main(String[] args) {</span></span>
<span class="line"><span>    List&lt;Object&gt; list = new ArrayList&lt;Object&gt;();</span></span>
<span class="line"><span>    for (int i = 0; i &lt; 1000; i++) {</span></span>
<span class="line"><span>      list.add(new char[1000000]);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ Javac TestClass.java</span></span>
<span class="line"><span>$ java -XX:+HeapDumpOnOutOfMemoryError -Xms10m -Xmx1g TestClass</span></span>
<span class="line"><span>java.lang.OutOfMemoryError: java heap space</span></span>
<span class="line"><span>Dumping heap to java_pid444496.hprof ...</span></span>
<span class="line"><span>Heap dump file created [1018925828 bytes in 1.442 secs]</span></span>
<span class="line"><span>Exception in thread &quot;main&quot; java.lang.OutOfMemoryError: java heap space</span></span>
<span class="line"><span>at TestClass.main(TestClass.Java:8)</span></span></code></pre></div>`,21)),n("p",null,[i(e,{href:"https://opensource.com/%5Bhttps%3A//docs.oracle.com/javase/7/docs/technotes/tools/share/jhat.html%5D%28https%3A//docs.oracle.com/javase/7/docs/technotes/tools/share/jhat.html%29"},{default:t(()=>[...a[6]||(a[6]=[s("有一些工具",-1)])]),_:1}),a[7]||(a[7]=s(" 可以查看这个 ",-1)),a[8]||(a[8]=n("code",null,".hprof",-1)),a[9]||(a[9]=s(" 文件以了解问题所在。",-1))]),a[28]||(a[28]=n("h3",{id:"总结",tabindex:"-1"},[s("总结 "),n("a",{class:"header-anchor",href:"#总结","aria-label":"Permalink to “总结”"},"​")],-1)),a[29]||(a[29]=n("p",null,"通过了解和使用 JVM 以及 JVM 参数，开发人员和终端用户都可以诊断故障并提高 Java 应用程序的性能。下次使用 Java 时，请花点时间看看有哪些参数可以用吧！",-1)),a[30]||(a[30]=n("hr",null,null,-1)),n("p",null,[a[11]||(a[11]=s("via: ",-1)),i(e,{href:"https://opensource.com/article/22/4/jvm-parameters-java-developers"},{default:t(()=>[...a[10]||(a[10]=[s("https://opensource.com/article/22/4/jvm-parameters-java-developers",-1)])]),_:1})]),n("p",null,[a[16]||(a[16]=s("作者：",-1)),i(e,{href:"https://opensource.com/users/jayashree-huttanagoudar"},{default:t(()=>[...a[12]||(a[12]=[s("Jayashree Huttanagoudar",-1)])]),_:1}),a[17]||(a[17]=s(" 选题：",-1)),i(e,{href:"https://github.com/lkxed"},{default:t(()=>[...a[13]||(a[13]=[s("lkxed",-1)])]),_:1}),a[18]||(a[18]=s(" 译者：",-1)),i(e,{href:"https://github.com/Veryzzj"},{default:t(()=>[...a[14]||(a[14]=[s("Veryzzj",-1)])]),_:1}),a[19]||(a[19]=s(" 校对：",-1)),i(e,{href:"https://github.com/wxy"},{default:t(()=>[...a[15]||(a[15]=[s("wxy",-1)])]),_:1})]),n("p",null,[a[22]||(a[22]=s("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...a[20]||(a[20]=[s("LCTT",-1)])]),_:1}),a[23]||(a[23]=s(" 原创编译，",-1)),i(e,{href:"https://linux.cn/"},{default:t(()=>[...a[21]||(a[21]=[s("Linux中国",-1)])]),_:1}),a[24]||(a[24]=s(" 荣誉推出",-1))])])}const j=l(h,[["render",c]]);export{J as __pageData,j as default};
